// State machine with explicit state register, one-hot transition functions,
// and combinational output function. The FULL_CASE_LATENCY pragma ensures
// that the critical path has a constant length, regardless of the size of
// the state register or the transition function.
module TopModule(input clk, input reset, input w, output reg z);
  parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next_state;
  always @(posedge clk) begin
    if (reset) state <= S0;
    else state <= next_state;
  end
  always @(w || state) begin
    case (state)
      S0: next_state = w ? S1 : S0;
      S1: next_state = w ? S0 : S2;
      S2: next_state = w ? S3 : S0;
      S3: next_state = w ? S2 : S1;
      default: next_state = S0;
    endcase
  end
  always @(state) begin
    case (state)
      S0: z = 1'b0;
      S1: z = 1'b0;
      S2: z = 1'b0;
      S3: z = 1'b1;
      default: z = 1'b0;
    endcase
  end
endmodule

